resolve_path_with_constants.source:
def resolve_path_with_constants(raw_path: str | None, base_dir: Path, constants: dict[str, str] | None = None) -> dict[str, Any]:
    original = "" if raw_path is None else str(raw_path)
    constants = constants or _workplace_registry_reader.load_workplace_path_constants(None, base_dir)
    expanded, used_constants, errors = _workplace_registry_reader.expand_path_constants(original, constants)
    expanded = normalize_path_string(expanded)
    status = "resolved"
    if errors:
        status = "error"
    elif used_constants:
        status = "resolved_from_constant"
    elif path_string_is_absolute(expanded):
        status = "absolute"
    else:
        status = "resolved_relative"
    if path_string_is_absolute(expanded):
        resolved = expanded
        is_absolute = True
    else:
        resolved = normalize_path_string((base_dir / expanded).resolve().as_posix())
        is_absolute = True
    return {
        "original": original,
        "expanded": expanded,
        "resolved": resolved,
        "is_absolute": is_absolute,
        "is_private": is_absolute,
        "path_status": status,
        "constants": used_constants,
        "errors": errors,
    }

